document.addEventListener("DOMContentLoaded",()=>{const e=[{label:"Introduced",value:"2005–2006"},{label:"Service Type",value:"Long-Distance AC"},{label:"Coach Class",value:"AC 3-Tier Only"},{label:"First Route",value:"Saharsa – Amritsar"}],a=document.getElementById("quick-facts-container");a&&e.forEach(e=>{const n=document.createElement("div");n.className="fact-card",n.innerHTML=`\n                <div class="fact-label">${e.label}</div>\n                <div class="fact-value">${e.value}</div>\n            `,a.appendChild(n)});const n=[{year:"2005",title:"Concept Announced",description:"The Garib Rath concept was announced in the Indian Railway Budget 2005–06 by Railway Minister Lalu Prasad Yadav, aiming to make AC travel affordable for ordinary passengers."},{year:"2006",title:"Inaugural Run",description:"The first Garib Rath Express began operating on 4 October 2006 between Saharsa Junction in Bihar and Amritsar Junction in Punjab."},{year:"2007–2012",title:"Network Expansion",description:"Additional Garib Rath services were introduced connecting major metros, industrial hubs and pilgrimage centres across the country."},{year:"Present",title:"Ongoing Service",description:"Several Garib Rath routes continue to run today, while some have since been rebranded or reconfigured as passenger preferences have shifted toward newer AC train categories."}],i=document.getElementById("timeline-container");i&&n.forEach(e=>{const a=document.createElement("div");a.className="timeline-item",a.tabIndex=0,a.innerHTML=`\n                <div class="timeline-year">${e.year}</div>\n                <div class="timeline-content">\n                    <h3>${e.title}</h3>\n                    <p>${e.description}</p>\n                </div>\n            `,i.appendChild(a)});const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-item").forEach(e=>t.observe(e));const r=[{title:"All-AC 3-Tier Coaches",description:"Every coach on a Garib Rath rake is AC 3-Tier — there is no sleeper, AC 2-Tier or first-class accommodation on board."},{title:"Higher-Density Seating",description:"Coaches carry more berths per coach than a standard AC 3-Tier coach, lowering the cost per passenger and keeping fares affordable."},{title:"Pay-As-You-Use Amenities",description:"Bedrolls and full meals, complimentary on many premium AC trains, are typically offered on Garib Rath at an additional cost to keep base fares low."}],o=document.getElementById("features-container");o&&r.forEach(e=>{const a=document.createElement("div");a.className="feature-card",a.tabIndex=0,a.innerHTML=`\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            `,o.appendChild(a)});const s=[{origin:"Saharsa Junction",destination:"Amritsar Junction",importantStations:["Patna","Lucknow","Delhi","Ambala"],regions:["Bihar","Uttar Pradesh","Delhi","Punjab"]},{origin:"Delhi Sarai Rohilla",destination:"Bikaner",importantStations:["Rewari","Sikar","Churu"],regions:["Delhi","Haryana","Rajasthan"]},{origin:"Kolkata",destination:"Yesvantpur (Bengaluru)",importantStations:["Bhubaneswar","Vijayawada","Chennai"],regions:["West Bengal","Odisha","Andhra Pradesh","Tamil Nadu","Karnataka"]},{origin:"Chennai Egmore",destination:"Hazrat Nizamuddin (Delhi)",importantStations:["Vijayawada","Nagpur","Jhansi"],regions:["Tamil Nadu","Andhra Pradesh","Maharashtra","Madhya Pradesh","Delhi"]},{origin:"Bandra Terminus",destination:"Amritsar Junction",importantStations:["Surat","Vadodara","Kota","Delhi"],regions:["Maharashtra","Gujarat","Rajasthan","Delhi","Punjab"]}],c=document.getElementById("routes-container");c&&(c.innerHTML=s.map(e=>`\n            <div class="route-card">\n                <div>\n                    <div class="origin-dest">${e.origin} → ${e.destination}</div>\n                    <div class="stations"><strong>Via:</strong> ${e.importantStations.join(", ")}</div>\n                </div>\n                <div class="regions-tag">${e.regions.join(" · ")}</div>\n            </div>\n        `).join(""));const d=[{icon:"🛏️",title:"AC 3-Tier Berths",description:"Air-conditioned sleeping accommodation throughout the train, with side and main berths arranged in a higher-density layout."},{icon:"🔌",title:"Charging Points",description:"Refurbished rakes include mobile and device charging points at berths for long-distance convenience."},{icon:"🍽️",title:"On-Demand Catering",description:"Meals and snacks are generally available for purchase on board, rather than included automatically in the base fare."},{icon:"📢",title:"Passenger Information",description:"Station announcements and coach-level signage help passengers track upcoming stops on long overnight journeys."},{icon:"🛡️",title:"Safety Features",description:"Coaches are fitted with fire and smoke detection systems, along with standard emergency alarm chains in every compartment."},{icon:"🚻",title:"Bio-Toilets",description:"Newer rakes are fitted with zero-discharge bio-toilets, improving hygiene and reducing environmental impact along the route."}],l=document.getElementById("facilities-container");l&&d.forEach(e=>{const a=document.createElement("div");a.className="facility-card",a.tabIndex=0,a.innerHTML=`\n                <div class="facility-icon" aria-hidden="true">${e.icon}</div>\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            `,l.appendChild(a)});const h=['"Garib Rath" translates from Hindi as "chariot of the poor," reflecting the service\'s affordability-first design goal.',"Garib Rath coaches typically seat around 81 berths per AC 3-Tier coach, compared to about 64 in a standard AC 3-Tier coach.","The first Garib Rath Express connected Saharsa in Bihar to Amritsar in Punjab, linking a major source region for migrant labour to a key destination hub."],m=document.getElementById("trivia-container");m&&h.forEach(e=>{const a=document.createElement("div");a.className="trivia-card",a.tabIndex=0,a.innerHTML=`<p>${e}</p>`,m.appendChild(a)})});